// ResortList.js
import React from 'react';

const ResortList = ({ resorts }) => (
  <ul>
    {resorts.length > 0 ? (
      resorts.map((resort) => (
        <li key={resort.slug || 'unknown'}>
          {resort.name || 'Unknown Resort'}
        </li>
      ))
    ) : (
      <li>No resorts found</li>
    )}
  </ul>
);

export default ResortList;
